parameters.jsCode:
const m = $input.first().json.body.message;
const sd = (m.analysis && m.analysis.structuredData) || {};
const num = (m.customer && m.customer.number) || (m.call && m.call.customer && m.call.customer.number) || null;
const started = m.startedAt ? new Date(m.startedAt) : null;
const ended = m.endedAt ? new Date(m.endedAt) : null;
const budgetLabel = { under_2k: 'Under $2k', '2k_to_10k': '$2k–$10k', over_10k: 'Over $10k', not_sure: 'Not sure' };
const timelineLabel = { asap: 'ASAP', this_quarter: 'This quarter', exploring: 'Just exploring' };
return [{ json: {
  call_id: m.call && m.call.id,
  call_type: (m.call && m.call.type) || 'unknown',
  caller_number: num || 'web call',
  started_at: m.startedAt || null,
  duration_sec: started && ended ? Math.round((ended - started) / 1000) : null,
  cost_usd: typeof m.cost === 'number' ? Number(m.cost.toFixed(3)) : null,
  ended_reason: m.endedReason || null,
  summary: (m.analysis && m.analysis.summary) || m.summary || '',
  success: (m.analysis && m.analysis.successEvaluation) || null,
  transcript: (m.artifact && m.artifact.transcript) || '',
  recording_url: (m.artifact && m.artifact.recordingUrl) || '',
  name: sd.name || 'Unknown caller',
  company: sd.company || '',
  need: sd.need || 'other',
  need_details: sd.need_details || '',
  budget_band: sd.budget_band || 'not_sure',
  budget_label: budgetLabel[sd.budget_band] || 'Not sure',
  timeline: sd.timeline || 'exploring',
  timeline_label: timelineLabel[sd.timeline] || 'Just exploring',
  decision_maker: sd.decision_maker === true,
  email: (sd.email || '').toLowerCase().trim(),
  booking_confirmed: sd.booking_confirmed === true,
  booked_slot: sd.booked_slot || '',
  not_a_fit: sd.not_a_fit === true
}}];

values.content:
=Score this inbound sales lead for a digital agency (websites, chatbots, automation).

Lead fields:
- Name: {{ $json.name }} ({{ $json.company }})
- Need: {{ $json.need }} — {{ $json.need_details }}
- Budget: {{ $json.budget_label }}
- Timeline: {{ $json.timeline_label }}
- Decision maker: {{ $json.decision_maker }}
- Booking confirmed: {{ $json.booking_confirmed }}
- Flagged not a fit: {{ $json.not_a_fit }}

Transcript:
{{ $json.transcript }}

Return ONLY a JSON object with exactly these keys:
score (integer 0-100), tier (one of: hot, warm, cold), reasoning (one sentence), next_action (one short imperative sentence for the sales rep).
Scoring guide: budget over $2k, ASAP/this-quarter timeline and decision-maker each add strongly; 'not sure' budget or 'just exploring' lowers; not_a_fit = score under 10.

parameters.jsCode:
const lead = $('Normalize Lead').first().json;
const raw = $input.first().json;
// Find the model text in whatever shape the Gemini node returned
let text = '';
if (typeof raw === 'string') text = raw;
else if (raw.content && raw.content.parts) text = raw.content.parts.map(p => p.text || '').join('');
else if (raw.candidates) text = ((raw.candidates[0] || {}).content || {}).parts?.map(p => p.text || '').join('') || '';
else if (typeof raw.text === 'string') text = raw.text;
else if (raw.score !== undefined) text = JSON.stringify(raw);
else text = JSON.stringify(raw);
let parsed = {};
try { parsed = JSON.parse(text); } catch (e) {
  const m = text.match(/\{[\s\S]*\}/); if (m) { try { parsed = JSON.parse(m[0]); } catch (e2) {} }
}
let score = Number(parsed.score);
if (!Number.isFinite(score)) {
  // deterministic fallback so the pipeline never stalls
  score = 20 + (lead.budget_band === 'over_10k' ? 35 : lead.budget_band === '2k_to_10k' ? 25 : 0)
        + (lead.timeline === 'asap' ? 20 : lead.timeline === 'this_quarter' ? 10 : 0)
        + (lead.decision_maker ? 15 : 0) + (lead.booking_confirmed ? 10 : 0);
  if (lead.not_a_fit) score = 5;
}
score = Math.max(0, Math.min(100, Math.round(score)));
const tier = ['hot','warm','cold'].includes(parsed.tier) ? parsed.tier : (score >= 70 ? 'hot' : score >= 40 ? 'warm' : 'cold');
const emoji = { hot: '🔥', warm: '🌤️', cold: '🧊' }[tier];
return [{ json: { ...lead, score, tier, tier_emoji: emoji,
  reasoning: parsed.reasoning || 'Scored by fallback rules (model output unparseable).',
  next_action: parsed.next_action || 'Review transcript and follow up by email.',
  scored_at: new Date().toISOString() } }];
